import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        sc.nextLine();

        List<Integer> numbers = new ArrayList<>();
        if (n > 0) {
            String line = sc.nextLine().trim();
            numbers = Arrays.stream(line.split("\\s+"))
                           .map(Integer::parseInt)
                           .collect(Collectors.toList());
        }

        double result = new SumOfSquares<Integer>().computeSumOfSquares(numbers);
        System.out.println("Sum of Squares: " + result);
    }
}

class SumOfSquares<T extends Number> {
    public double computeSumOfSquares(List<T> list) {
        double sum = 0.0;
        for (T num : list) {
            double value = num.doubleValue();
            sum += value * value;
        }
        return sum;
    }
}
